import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const createTaskInput = z.object({ task_id: z.string().min(1), title: z.string().min(1) });
export const createTaskOutput = z.object({ task_id: z.string(), title: z.string(), status: z.literal('pending') });
export type CreateTaskInput = z.infer<typeof createTaskInput>;
export type CreateTaskOutput = z.infer<typeof createTaskOutput>;

@AgentUseCase({ name: 'create_task', description: 'Cria, salva e publica uma tarefa pendente; id repetido falha com TASK_ALREADY_EXISTS.', whenToUse: 'Quando o usuário deseja criar uma tarefa.', whenNotToUse: 'Para concluir tarefa existente.', input: createTaskInput, output: createTaskOutput, uses: ['method:Task.create'], emits: [TaskCreated] })
export class CreateTask implements UseCase<CreateTaskInput, CreateTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CreateTaskInput, ctx: UseCaseContext): Promise<CreateTaskOutput> {
    const existing = await this.tasks.findById(input.task_id);
    if (existing) {
      throw new DomainError('TASK_ALREADY_EXISTS', 'A tarefa já existe.');
    }
    const task = Task.create(input.task_id, input.title);
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, title: task.title, status: 'pending' };






  }
}

import { expect, test } from 'bun:test';
import { DomainError, type UseCaseContext } from '@agentic-ddd/core';
import { covers, createTestContext } from '@agentic-ddd/testing';
import { CreateTask, createTaskOutput } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

test(covers([
  'usecase:create_task',
  'criterion:0001/persistencia-criacao',
], 'salva t1 pending antes de publicar TaskCreated e rejeita repetição sem efeitos adicionais'), async () => {
  const persisted = new InMemoryTaskRepository();
  expect(await persisted.findById('t1')).toBeNull();
  const steps: string[] = [];
  const tasks: TaskRepository = {
    async findById(id) {
      steps.push(`load:${id}`);
      return persisted.findById(id);
    },
    async save(task) {
      await persisted.save(task);
      steps.push('saved');
    },
  };
  const context = createTestContext();
  const ctx: UseCaseContext = {
    ...context,
    async publish(events) {
      expect(steps).toEqual(['load:t1', 'saved']);
      const saved = await persisted.findById('t1');
      expect(saved?.title).toBe('Minha  tarefa');
      expect(saved?.status).toBe('pending');
      await context.publish(events);
      steps.push('published');
    },
  };
  const useCase = new CreateTask(tasks);

  const output = await useCase.execute({ task_id: 't1', title: ' \tMinha  tarefa\n ' }, ctx);

  expect(output).toEqual({ task_id: 't1', title: 'Minha  tarefa', status: 'pending' });
  expect(createTaskOutput.parse(output)).toEqual(output);
  expect(steps).toEqual(['load:t1', 'saved', 'published']);
  expect(context.published).toHaveLength(1);
  expect(context.published[0]).toBeInstanceOf(TaskCreated);
  expect(context.published[0]!.payload).toEqual({ taskId: 't1', title: 'Minha  tarefa' });
  const saved = await persisted.findById('t1');
  expect(saved?.pullEvents()).toEqual([]);

  const repetition = useCase.execute({ task_id: 't1', title: 'Outro título' }, ctx);

  await expect(repetition).rejects.toBeInstanceOf(DomainError);
  await expect(repetition).rejects.toMatchObject({ code: 'TASK_ALREADY_EXISTS' });
  expect(steps).toEqual(['load:t1', 'saved', 'published', 'load:t1']);
  expect(await persisted.findById('t1')).toBe(saved);
  expect(saved?.title).toBe('Minha  tarefa');
  expect(saved?.status).toBe('pending');
  expect(context.published).toHaveLength(1);
});

test(covers(['usecase:create_task'], 'rejeita título composto de espaços sem salvar ou publicar'), async () => {
  let saves = 0;
  const tasks: TaskRepository = {
    async findById() { return null; },
    async save() { saves += 1; },
  };
  const context = createTestContext();

  const execution = new CreateTask(tasks).execute({ task_id: 't1', title: ' \t\n ' }, context);

  await expect(execution).rejects.toBeInstanceOf(DomainError);
  await expect(execution).rejects.toMatchObject({ code: 'TASK_TITLE_REQUIRED' });
  expect(saves).toBe(0);
  expect(context.published).toEqual([]);
});

test(covers(['usecase:create_task'], 'propaga falha de consulta sem salvar ou publicar'), async () => {
  const failure = new Error('Falha ao consultar');
  let saves = 0;
  const tasks: TaskRepository = {
    async findById() { throw failure; },
    async save() { saves += 1; },
  };
  const context = createTestContext();

  await expect(new CreateTask(tasks).execute({ task_id: 't1', title: 'Tarefa' }, context)).rejects.toBe(failure);

  expect(saves).toBe(0);
  expect(context.published).toEqual([]);
});

test(covers(['usecase:create_task'], 'propaga falha de persistência sem publicar TaskCreated'), async () => {
  const failure = new Error('Falha ao salvar');
  const tasks: TaskRepository = {
    async findById() { return null; },
    async save() { throw failure; },
  };
  const context = createTestContext();

  await expect(new CreateTask(tasks).execute({ task_id: 't1', title: 'Tarefa' }, context)).rejects.toBe(failure);

  expect(context.published).toEqual([]);
});
